import{_ as a,o as i,c as o,a2 as s}from"./chunks/framework.BN2sqjC1.js";const g=JSON.parse('{"title":"Matrice manuale — client desktop su Wails v3 (M15)","description":"","frontmatter":{},"headers":[],"relativePath":"qa/m15-wails3-matrice.md","filePath":"qa/m15-wails3-matrice.md"}'),n={name:"qa/m15-wails3-matrice.md"};function t(l,e,r,d,c,p){return i(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="matrice-manuale-—-client-desktop-su-wails-v3-m15" tabindex="-1">Matrice manuale — client desktop su Wails v3 (M15) <a class="header-anchor" href="#matrice-manuale-—-client-desktop-su-wails-v3-m15" aria-label="Permalink to &quot;Matrice manuale — client desktop su Wails v3 (M15)&quot;">​</a></h1><p>Da eseguire sui <strong>binari di rilascio</strong> (non sul dev server) di macOS, Windows 11 e Ubuntu 22.04 e 24.04, prima di accettare <a href="./../adr/0051-wails-v3.html">ADR-0051</a>. Gli automatismi (vitest dello shim, <code>go test -race</code>, e2e su mock dei binding, smoke del binario) non vedono la finestra nativa: qui si verifica quello che solo un sistema operativo vero può dire. Uscita della milestone: <strong>zero P0 e P1</strong>. P0 = perdita di dati alla chiusura, login o deep link rotti, installazione sopra la 1.3.4 fallita (o aggiornamento fallito, per le build con chiave), crash all&#39;avvio. <strong>Nessun rollback a Wails v2</strong> (decisione dell&#39;owner, 2026-11-11, <a href="./../adr/0051-wails-v3.html">ADR-0051</a>): un P0 si corregge in avanti su v3.</p><blockquote><p><strong>Nota (2026-11-20).</strong> <a href="./../adr/0051-wails-v3.html">ADR-0051</a> è stato <strong>accettato lo stesso giorno senza che questa matrice fosse eseguita</strong> (decisione dell&#39;owner, opzione A della proposta di spec v1.8; <code>Specifications.md</code> v1.8 dice Wails v3.1.0). La matrice resta da eseguire e il rischio su Windows e Linux resta dichiarato; il testo qui sotto è quello originale.</p></blockquote><p>Segnare <code>[x]</code> con data, sistema operativo e versione provata; un difetto va annotato sotto la voce con il suo livello (P0, P1, P2).</p><h2 id="stato-al-2026-11-11-onda-b-w7" tabindex="-1">Stato al 2026-11-11 (onda B-W7) <a class="header-anchor" href="#stato-al-2026-11-11-onda-b-w7" aria-label="Permalink to &quot;Stato al 2026-11-11 (onda B-W7)&quot;">​</a></h2><ul><li><strong>Provato su macOS (arm64, Go 1.27, Wails 3.1.0):</strong> <code>task release-desktop OS=darwin V=…</code> e <code>scripts/release/package-macos.sh</code> producono <code>memobrain-&lt;V&gt;-darwin-universal.dmg</code> con <code>MemoBrain Notes.app</code> (x86_64 e arm64, firma ad hoc valida, <code>Info.plist</code> con <code>dev.memobrain.desktop</code>, <code>CFBundleExecutable memobrain</code>, versione stampata); l&#39;app copiata dal <code>.dmg</code> si avvia con una data dir temporanea e, con SIGTERM, chiude subito scrivendo «stopped». Controllo dei tag del binario: <code>production</code> presente, <code>mcp</code>, <code>server</code> e <code>devtools</code> assenti.</li><li><strong>Provato solo come cross-build (macOS → Windows):</strong> <code>task release-desktop OS=windows</code> produce <code>memobrain.exe</code> (PE GUI, manifest e versione 1.3.5.0 resi) e <code>memobrain-amd64-installer.exe</code> con <code>makensis</code>; i template NSIS, manifest e <code>info.json</code> resi coincidono con quelli di v2 (stesse chiavi di registro, percorsi, <code>MemoBrain Notes.exe</code>, <code>Software\\Classes\\memobrain</code>).</li><li><strong>Mai eseguito:</strong> tutto il resto di questo documento. In particolare nessun avvio su Windows e Linux, nessuna build Linux con <code>-tags gtk3</code>, nessuna prova di aggiornamento, né via updater (§3) né con l&#39;installazione manuale sopra la 1.3.4 (§1.1).</li><li><strong>Nessun rollback a v2</strong> (decisione dell&#39;owner, 2026-11-11): in caso di problemi gravi si corregge in avanti su v3. La matrice non prova quindi nessun ritorno a una v2.</li><li><strong>Criterio di aggiornamento di M15 (decisione dell&#39;owner, 2026-11-11):</strong> le build pubblicate non hanno l&#39;aggiornamento automatico, quindi il criterio è l&#39;installazione manuale sopra la 1.3.4 su ogni sistema operativo (§1.1). L&#39;aggiornamento via updater (§3) resta da provare solo per build compilate con una chiave.</li></ul><h2 id="esiti-automatici-2026-11-11" tabindex="-1">Esiti automatici (2026-11-11) <a class="header-anchor" href="#esiti-automatici-2026-11-11" aria-label="Permalink to &quot;Esiti automatici (2026-11-11)&quot;">​</a></h2><p>Eseguiti da QA sul ramo di migrazione, macchina macOS arm64 sotto alimentazione di rete, Docker 29.9.3 disponibile, <code>caffeinate -i</code>. I log delle esecuzioni non sono versionati: valgono i numeri riportati qui sotto. Qui si prova solo quello che si può automatizzare: <strong>nessuna riga manuale di questo documento è stata spuntata</strong>.</p><h3 id="suite" tabindex="-1">Suite <a class="header-anchor" href="#suite" aria-label="Permalink to &quot;Suite&quot;">​</a></h3><ul><li><strong>Integrazione cloud</strong> (<code>task test-integration</code>, testcontainers): ok, <code>test/integration</code> 128,8 s, 2 min 16 s totali.</li><li><strong>Sync a due dispositivi</strong> (<code>task test-desktop-e2e</code>): ok, <code>internal/sync</code> 226,2 s e <code>internal/sync/transport</code> 21,2 s, 3 min 49 s totali.</li><li><strong><code>task e2e</code></strong> (desktop-mock, bundle di produzione, console web): ok, 127 + 43 + 94 = 264 passati, 36 saltati (solo nel primo gruppo), 3 min 24 s.</li><li><strong><code>task e2e-matrix</code></strong> (spec desktop su desktop-mock e web-core): al primo giro 245 passati, 77 saltati, <strong>4 falliti</strong> in 11 min 15 s: <code>drawing-wp5.spec.ts:79</code> e <code>:93</code> su desktop-mock, <code>drawing-embed.spec.ts:105</code> e <code>:125</code> su web-core. Tutti e quattro con lo stesso errore, <code>browserContext.close: ENOENT</code> su un file di traccia in <code>.dev/e2e-matrix/5199-5176/test-results/</code> (la cartella dei risultati è sparita sotto i piedi di Playwright: sulla macchina girava in parallelo un altro <code>e2e:workbench-ui</code>), mai un&#39;asserzione. Rilanciate le due spec con <code>--repeat-each=3</code> su entrambi i target: 114 passati, 0 falliti, 6 saltati, 8 min 24 s. Classificazione: ambiente, non regressione. Per una prova pulita rieseguire la matrice intera a macchina libera.</li></ul><h3 id="smoke-del-binario-v3-reale-macos-universale-versione-1-3-5-qa" tabindex="-1">Smoke del binario v3 reale (macOS universale, versione <code>1.3.5-qa</code>) <a class="header-anchor" href="#smoke-del-binario-v3-reale-macos-universale-versione-1-3-5-qa" aria-label="Permalink to &quot;Smoke del binario v3 reale (macOS universale, versione \`1.3.5-qa\`)&quot;">​</a></h3><p>Build: <code>scripts/build-desktop-bin.sh --version 1.3.5-qa</code> (17 s con cache calda; lo script scrive sempre in <code>apps/desktop/build/bin/</code>, cartella ignorata da git: il bundle è stato copiato nello scratchpad e la <code>MemoBrain Notes.app</code> preesistente ripristinata). Binario lanciato direttamente, con <code>MEMOBRAIN_DATA_DIR</code> temporanea.</p><ul><li><strong>Avvio:</strong> il log <code>&lt;data dir&gt;/logs/memobrain.log</code> scrive «started» (versione <code>1.3.5-qa</code>) in 1,4 s.</li><li><strong>Seconda istanza, stessa data dir, con <code>memobrain://open?…</code>:</strong> esce con codice 0 dopo 0,6 s, la prima resta viva e registra «second instance launch» con l&#39;URL oscurato. Non verificato: l&#39;apertura della nota (nessun vault nello smoke).</li><li><strong>Seconda istanza, data dir diversa:</strong> convive (entrambi i processi vivi, un solo «started» per log).</li><li><strong>SIGTERM:</strong> entrambi i processi terminano in 0,15 s e il log chiude con «stopped» (soglia 5 s). Nessun processo residuo. Nessuna nota modificata nello smoke: il giro con nota sporca resta nella matrice manuale.</li><li><strong>Tag:</strong> <code>scripts/release/check-build-tags.sh</code> ok su entrambe le slice (x86_64 e arm64: tags <code>production</code>). <code>go version -m</code>: <code>-tags=production</code>, <code>-trimpath=true</code>, <code>CGO_ENABLED=1</code>, Go 1.27.4; nessuna traccia di <code>mcp</code>, <code>server</code>, <code>devtools</code>. La porta 9099 non è in ascolto.</li><li><strong>Dimensione:</strong> 129.624.928 byte contro i 127.936.608 della 1.3.4 installata in <code>/Applications</code> (+1.688.320 byte, +1,3%, entrambe universali). Il <code>.dmg</code> della 1.3.5 non è stato costruito qui.</li></ul><p>Per rieseguire: <code>scripts/build-desktop-bin.sh --version 1.3.5-qa</code>, poi <code>MEMOBRAIN_DATA_DIR=$(mktemp -d) &quot;apps/desktop/build/bin/MemoBrain Notes.app/Contents/MacOS/memobrain&quot;</code>, e dalla stessa data dir una seconda esecuzione con l&#39;URL; <code>scripts/release/check-build-tags.sh</code> sul binario.</p><h3 id="ancora-da-eseguire" tabindex="-1">Ancora da eseguire <a class="header-anchor" href="#ancora-da-eseguire" aria-label="Permalink to &quot;Ancora da eseguire&quot;">​</a></h3><p>Windows 11, Ubuntu 22.04 e 24.04 e macOS Intel: nessuna prova (le righe sotto e il registro in §4 restano da compilare). Su macOS arm64 restano manuali la finestra nativa, il drop dei file, i dialoghi, il giro di chiusura con nota sporca (20 prove), i deep link a freddo e a caldo e l&#39;installazione sopra la 1.3.4 (§1.1).</p><h2 id="_0-costruire-i-binari-da-provare" tabindex="-1">0. Costruire i binari da provare <a class="header-anchor" href="#_0-costruire-i-binari-da-provare" aria-label="Permalink to &quot;0. Costruire i binari da provare&quot;">​</a></h2><p>Dalla radice del repository, con la CLI <code>wails3</code> installata (<code>task wails-cli</code>) solo per Windows:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># macOS (universale) → dist/memobrain-&lt;V&gt;-darwin-universal.dmg</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ALLOW_UNSIGNED_UPDATES</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release-desktop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> OS=darwin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> V=1.3.5-rc.1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/release/package-macos.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1.3.5-rc.1</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Windows (anche da macOS con makensis) → apps/desktop/build/bin/memobrain-amd64-installer.exe</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ALLOW_UNSIGNED_UPDATES</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release-desktop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> OS=windows</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ARCH=amd64</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> V=1.3.5-rc.1</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Linux (su Ubuntu con libgtk-3-dev e libwebkit2gtk-4.1-dev) → dist/*.deb e *.AppImage</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ALLOW_UNSIGNED_UPDATES</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release-desktop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> OS=linux</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> V=1.3.5-rc.1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/release/package-linux.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> all</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1.3.5-rc.1</span></span></code></pre></div><p><code>task release-desktop</code> passa <code>--release</code> a <code>scripts/release/build-desktop.sh</code>: rifiuta la build senza <code>UPDATE_PUBLIC_KEY</code> e <code>UPDATE_BASE_URL</code> (salvo <code>ALLOW_UNSIGNED_UPDATES=1</code>) e rifiuta <code>MEMOBRAIN_AI</code>, <code>MEMOBRAIN_COLLAB</code>, <code>MEMOBRAIN_E2E</code> e <code>MEMOBRAIN_DIST</code> nell&#39;ambiente (<code>MEMOBRAIN_LIVE_ENGINE</code> non esiste più dal 2026-11-12: ogni build ha Live su Milkdown, ADR-0049). Per le prove di §1.1 (build come quelle pubblicate) si usa <code>ALLOW_UNSIGNED_UPDATES=1</code>, che compila l&#39;updater fuori dal binario, come <code>release.yml</code>: negli esempi sotto è già indicato. Per le prove di §3 servono invece chiave e URL di staging, <strong>senza</strong> <code>ALLOW_UNSIGNED_UPDATES</code>. Prima di ogni sessione: <code>scripts/release/check-build-tags.sh</code> sul binario (lo esegue già la build) e, su Linux, <code>ldd memobrain | grep -E &#39;webkit|gtk&#39;</code> deve mostrare <code>libwebkit2gtk-4.1</code> e <code>libgtk-3</code>.</p><h2 id="_1-installazione-e-disinstallazione" tabindex="-1">1. Installazione e disinstallazione <a class="header-anchor" href="#_1-installazione-e-disinstallazione" aria-label="Permalink to &quot;1. Installazione e disinstallazione&quot;">​</a></h2><ul><li>[ ] <strong>Windows:</strong> l&#39;installer chiede l&#39;elevazione, installa in <code>C:\\Program Files\\E2BR-Advisory Sagl\\MemoBrain Notes\\</code> un solo <code>MemoBrain Notes.exe</code>, crea i collegamenti (menu Start e desktop) e <strong>una sola</strong> voce «MemoBrain Notes» in <em>App installate</em> (chiave <code>Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\E2BR-Advisory SaglMemoBrain Notes</code>). Se WebView2 manca, il bootstrapper lo installa.</li><li>[ ] <strong>Windows:</strong> <code>HKLM\\Software\\Classes\\memobrain</code> (<code>URL Protocol</code>, <code>shell\\open\\command</code> verso <code>MemoBrain Notes.exe &quot;%1&quot;</code>) esiste dopo l&#39;installazione e sparisce con la disinstallazione.</li><li>[ ] <strong>Windows:</strong> la disinstallazione rimuove cartella, collegamenti, chiave di registro e <code>%AppData%\\MemoBrain Notes.exe</code> (dati di WebView2); <strong>non</strong> tocca la data dir dell&#39;app né i vault.</li><li>[ ] <strong>macOS:</strong> il <code>.dmg</code> mostra <code>MemoBrain Notes.app</code> e il collegamento ad Applications; trascinata in <code>/Applications</code> si avvia (Gatekeeper avvisa: è non firmata); su macOS 12 o precedente Finder dice che serve macOS 13.</li><li>[ ] <strong>Linux:</strong> il <code>.deb</code> si installa (<code>sudo apt install ./memobrain-*.deb</code> porta <code>libgtk-3-0</code> e <code>libwebkit2gtk-4.1-0</code>), l&#39;icona compare nel menu e <strong>nel dock</strong> (<code>StartupWMClass</code>/<code>ProgramName</code> <code>memobrain</code>); l&#39;AppImage si avvia con <code>--appimage-extract-and-run</code> e con FUSE.</li></ul><h3 id="_1-1-installazione-manuale-sopra-la-1-3-4-criterio-di-aggiornamento-di-m15" tabindex="-1">1.1 Installazione manuale sopra la 1.3.4 (criterio di aggiornamento di M15) <a class="header-anchor" href="#_1-1-installazione-manuale-sopra-la-1-3-4-criterio-di-aggiornamento-di-m15" aria-label="Permalink to &quot;1.1 Installazione manuale sopra la 1.3.4 (criterio di aggiornamento di M15)&quot;">​</a></h3><p>È il percorso che gli utenti seguono davvero, e per decisione dell&#39;owner (2026-11-11) è il criterio di aggiornamento di M15: le build pubblicate hanno l&#39;updater spento (<code>.github/workflows/release.yml:112</code> imposta <code>ALLOW_UNSIGNED_UPDATES: &#39;1&#39;</code> senza <code>UPDATE_PUBLIC_KEY</code>; <code>README.md</code> dice che le nuove versioni si installano a mano), quindi §3, che prova l&#39;aggiornamento via updater su un canale di staging, non lo copre e vale solo per build con chiave. Partire dagli installer veri della <strong>1.3.4</strong> (quelli pubblicati, nessun canale di staging) e installare sopra la build v3 (<code>1.3.5-rc.1</code> di §0, costruita come in <code>release.yml</code>: senza <code>UPDATE_PUBLIC_KEY</code> e con <code>ALLOW_UNSIGNED_UPDATES=1</code>).</p><ul><li>[ ] <strong>Windows:</strong> installare la 1.3.4 con il suo installer NSIS, aprire un vault di prova con note e un disegno, annotare cartella di installazione, data dir, vault recenti, impostazioni, <code>reg query HKLM\\Software\\Classes\\memobrain</code>, la chiave Uninstall e <code>%AppData%\\MemoBrain Notes.exe</code>. Lanciare sopra l&#39;installer v3 (<code>memobrain-&lt;V&gt;-windows-amd64.exe</code>, UAC): nessun avviso di «già installato», stessa <code>UNINST_KEY</code> (<code>E2BR-Advisory SaglMemoBrain Notes</code>), stessa <code>InstallDir</code> (<code>C:\\Program Files\\E2BR-Advisory Sagl\\MemoBrain Notes\\</code>), <strong>una sola</strong> voce in <em>App installate</em>, <code>MemoBrain Notes.exe</code> sostituito e non duplicato.</li><li>[ ] <strong>macOS:</strong> con la 1.3.4 in <code>/Applications</code> chiusa, trascinare sopra la <code>MemoBrain Notes.app</code> del <code>.dmg</code> v3 e scegliere <em>Sostituisci</em>: resta una sola app, Gatekeeper avvisa come per la 1.3.4 (non firmata), il bundle ID è <code>dev.memobrain.desktop</code>. Su macOS 12 o precedente il Finder rifiuta la v3 (serve macOS 13): la 1.3.4 resta com&#39;era.</li><li>[ ] <strong>Linux, <code>.deb</code>:</strong> con la 1.3.4 installata da <code>.deb</code>, <code>sudo apt install ./memobrain-&lt;V&gt;-linux-amd64.deb</code>: il pacchetto <code>memobrain</code> passa da 1.3.4 a 1.3.5 (<code>apt</code> lo tratta come un aggiornamento), resta una sola voce di menu e un solo eseguibile, l&#39;icona compare nel dock.</li><li>[ ] <strong>Linux, AppImage:</strong> sostituire il file della 1.3.4 con quello v3 (o lanciarlo accanto): stessa data dir, nessuna seconda cartella dati.</li><li>[ ] <strong>Dopo ogni installazione sopra</strong> le stesse verifiche di §3.4, punto 3: la versione in About è 1.3.5; c&#39;è una sola installazione; <strong>data dir, vault recenti, impostazioni e login</strong> sono quelli di prima senza rifare nulla; lo schema <code>memobrain://</code> funziona (W: chiave di registro intatta; M: <code>open memobrain://open?...</code>); W: <code>%AppData%\\MemoBrain Notes.exe</code> è la stessa cartella, senza una seconda cartella di dati di WebView2; il giro di chiusura con una nota modificata (§2) passa sulla build installata. Annotare gli strumenti recenti di Excalidraw (M e L): si azzerano una volta. <strong>Nessun ritorno a una v2</strong> (decisione dell&#39;owner, 2026-11-11): se un&#39;installazione sopra la 1.3.4 fallisce o la v3 ha un difetto grave, si corregge in avanti con una nuova versione v3. Chi ha già installato la v3 non scende di versione.</li></ul><h2 id="_2-funzioni-per-sistema-operativo" tabindex="-1">2. Funzioni per sistema operativo <a class="header-anchor" href="#_2-funzioni-per-sistema-operativo" aria-label="Permalink to &quot;2. Funzioni per sistema operativo&quot;">​</a></h2><p>Ogni voce vale per macOS (M), Windows (W) e Linux (L) se non diversamente indicato.</p><h3 id="chiusura-p0" tabindex="-1">Chiusura (P0) <a class="header-anchor" href="#chiusura-p0" aria-label="Permalink to &quot;Chiusura (P0)&quot;">​</a></h3><ul><li>[ ] Con una nota modificata e non salvata: chiusura col pulsante della finestra, poi con <strong>Cmd+Q</strong> (M) o <strong>Alt+F4</strong> (W, L), poi con «Esci» dell&#39;updater: il file viene scritto, <code>app:before-close</code> compare <strong>una sola volta</strong> nel log, il processo termina entro 5 s e il log chiude con <code>stopped</code>. <strong>20 prove per sistema operativo</strong> e per gesto, contando i file scritti.</li><li>[ ] Frontend che non risponde (ad esempio un loop nel devtools solo in una build di prova): la chiusura avviene dopo il timeout di 10 s, senza processi residui (Gestione attività, <code>ps</code>).</li><li>[ ] Chiusura mentre un export o un sync è in corso: nessun file troncato, nessuna copia di conflitto spuria alla riapertura.</li><li>[ ] SIGTERM/SIGINT (M, L): lo stesso giro di chiusura, senza perdita della nota.</li></ul><h3 id="deep-link-e-account-p0" tabindex="-1">Deep link e account (P0) <a class="header-anchor" href="#deep-link-e-account-p0" aria-label="Permalink to &quot;Deep link e account (P0)&quot;">​</a></h3><ul><li>[ ] <code>memobrain://open?...</code> con l&#39;app <strong>chiusa</strong> (avvio a freddo) e <strong>aperta</strong> (a caldo): la nota si apre, nessuna doppia consegna. <strong>10 prove su 10</strong> per sistema operativo.</li><li>[ ] Login OIDC con callback loopback e con il ripiego <code>memobrain://auth/callback</code>: il token torna all&#39;app (keychain: Portachiavi su M, Gestione credenziali su W, Secret Service su L).</li><li>[ ] <code>location.reload()</code> (ricarica dell&#39;interfaccia) con un deep link ancora in coda: il link viene consegnato una volta sola.</li><li>[ ] <strong>L:</strong> seconda istanza (single-instance) su <strong>Ubuntu 22.04 e 24.04</strong>, con 50 data dir diverse (<code>MEMOBRAIN_DATA_DIR=$(mktemp -d)</code>): la seconda istanza passa gli argomenti alla prima e termina; nessuna uscita all&#39;avvio (la regola D-Bus di v3 rifiuta l&#39;ID di v2 in 614 casi su 1000, il 61,4%: misura dello spike B-W0 sull&#39;ID, non un guasto osservato su Ubuntu). Sia X11 sia Wayland.</li><li>[ ] <strong>W:</strong> seconda istanza: l&#39;app aperta passa in primo piano e riceve l&#39;URL.</li></ul><h3 id="drop-di-file" tabindex="-1">Drop di file <a class="header-anchor" href="#drop-di-file" aria-label="Permalink to &quot;Drop di file&quot;">​</a></h3><ul><li>[ ] Trascinare un PNG da Finder (M), Esplora risorse (W) o Nautilus (L) nell&#39;<strong>editor</strong>, nel <strong>file explorer</strong> e su un disegno <strong>Excalidraw</strong>: l&#39;allegato viene creato dove ci si aspetta, la finestra non naviga.</li><li>[ ] Rilasciare un file <strong>fuori</strong> da ogni zona di drop: nessuna navigazione, nessun file aperto dal sistema.</li><li>[ ] Trascinare del testo e un&#39;immagine dal browser: stesso comportamento della 1.3.4.</li></ul><h3 id="dialoghi-con-«annulla»" tabindex="-1">Dialoghi, con «Annulla» <a class="header-anchor" href="#dialoghi-con-«annulla»" aria-label="Permalink to &quot;Dialoghi, con «Annulla»&quot;">​</a></h3><ul><li>[ ] Scelta della cartella del vault, «Apri un&#39;altra cartella…», import, «Salva una copia», Export HTML, Export ZIP: confermare salva/apre; <strong>«Annulla» non mostra errori</strong> e non cambia stato (anche su W: l&#39;helper dei dialoghi trasforma l&#39;annullamento in nessun errore; da verificare su Windows reale che il «Annulla» di <code>cfd</code> non faccia comparire nulla, P1).</li><li>[ ] I dialoghi sono agganciati alla finestra (sheet su M, finestra proprietaria su W e L): non restano dietro l&#39;app.</li><li>[ ] Il dialogo di errore all&#39;avvio (<code>app.db</code> illeggibile: provarlo rendendo il file non leggibile) compare una volta e l&#39;app esce.</li></ul><h3 id="export-grandi-e-chiamate-lunghe" tabindex="-1">Export grandi e chiamate lunghe <a class="header-anchor" href="#export-grandi-e-chiamate-lunghe" aria-label="Permalink to &quot;Export grandi e chiamate lunghe&quot;">​</a></h3><ul><li>[ ] <strong>W (WebView2) e L (WebKitGTK):</strong> export HTML da 65, 200 e 250 MiB con immagini incorporate; <code>SaveAttachment</code> da 32 MB; <code>ReadBinary</code> da 32 MB entro 1,25 volte il tempo della 1.3.4; una chiamata pendente per 3 minuti con altre in corso. Annotare tempi e memoria del processo WebView.</li><li>[ ] <strong>M:</strong> gli stessi export. Il trasporto è lo stesso delle altre piattaforme e non è il canale nativo dei messaggi: gli argomenti oltre 32 MiB di JSON salgono a pezzi di 512 KiB su <code>/memobrain/upload/&lt;id&gt;</code> dell&#39;asset server (B-W4b, ADR-0051). Già provato su macOS in un WKWebView reale (65, 200 e 250 MiB); qui si ripete sul binario di rilascio.</li><li>[ ] Export HTML con il dialogo «Salva» aperto per qualche minuto e un&#39;altra operazione in parallelo: nessun timeout.</li></ul><h3 id="menu-finestra-e-stampa" tabindex="-1">Menu, finestra e stampa <a class="header-anchor" href="#menu-finestra-e-stampa" aria-label="Permalink to &quot;Menu, finestra e stampa&quot;">​</a></h3><ul><li>[ ] <strong>M:</strong> menu App (senza Services), Edit (copia, incolla, annulla, ripeti, seleziona tutto) e Window; scorciatoie di modifica nell&#39;editor; voce About con la versione; <strong>Full Screen</strong> (l&#39;etichetta resta «Toggle Full Screen»).</li><li>[ ] <strong>W e L:</strong> nessuna barra dei menu; il menu contestuale nativo è assente.</li><li>[ ] <strong>M:</strong> titlebar con i semafori: l&#39;intestazione si può trascinare dalla parte vuota e i pulsanti non avviano il trascinamento.</li><li>[ ] Fullscreen delle presentazioni (<code>WindowFullscreen</code>, <code>WindowUnfullscreen</code>) e uscita con Esc; apertura di un link esterno (<code>BrowserOpenURL</code>) nel browser di sistema.</li><li>[ ] <strong>Stampa / Esporta in PDF:</strong> il dialogo di stampa si apre e il PDF è leggibile (formule, immagini, diagrammi). <strong>Esporta come immagine</strong> (PNG): non fallisce con «canvas tainted».</li><li>[ ] <code>navigator.clipboard.writeText</code> (copia di un link o di un blocco di codice) funziona.</li></ul><h3 id="sicurezza-e-compatibilita" tabindex="-1">Sicurezza e compatibilità <a class="header-anchor" href="#sicurezza-e-compatibilita" aria-label="Permalink to &quot;Sicurezza e compatibilità&quot;">​</a></h3><ul><li>[ ] La CSP di produzione non produce violazioni (console del devtools in una build di prova); un iframe <code>https</code> non carica; Excalidraw funziona <strong>senza rete</strong> (scollegare la rete prima di aprire un disegno).</li><li>[ ] Nel log, a uso normale, nessuna passphrase né contenuto di note (livello Warn minimo): sbloccare un vault privato e cercare la passphrase nel log (<code>&lt;data dir&gt;/logs/memobrain.log</code>).</li><li>[ ] Il binario non apre la porta 9099 in ascolto (<code>lsof -iTCP:9099 -sTCP:LISTEN</code> / <code>netstat -ano</code>): conferma l&#39;assenza del tag <code>mcp</code>.</li><li>[ ] <strong>M e L:</strong> gli strumenti recenti di Excalidraw sono azzerati una volta (l&#39;origine passa da <code>wails://wails</code> a <code>wails://localhost</code>): atteso, annotarlo. <strong>W:</strong> invariati.</li><li>[ ] Avvio a freddo: tempo fino alla prima interfaccia utilizzabile non peggiore di 1,5 volte quello della 1.3.4 (vault di 5.000 note).</li></ul><h2 id="_3-aggiornamento-1-3-4-→-v3-via-updater-solo-build-con-chiave" tabindex="-1">3. Aggiornamento 1.3.4 → v3 via updater (solo build con chiave) <a class="header-anchor" href="#_3-aggiornamento-1-3-4-→-v3-via-updater-solo-build-con-chiave" aria-label="Permalink to &quot;3. Aggiornamento 1.3.4 → v3 via updater (solo build con chiave)&quot;">​</a></h2><p>Prova l&#39;aggiornamento <strong>via updater</strong>, che le build pubblicate non hanno (vedi §1.1 per l&#39;installazione manuale, il percorso reale). Non eseguibile con i binari pubblicati: URL e chiave del canale sono compilati nel client (<code>internal/updater/key.go</code>) e l&#39;unico canale vero non si può usare per una prova. Serve un <strong>canale di staging</strong> e una 1.3.4 ricostruita con la sua chiave e il suo URL. Non è il criterio di M15 (vedi §1.1): serve solo se si distribuisce una build con chiave pubblica. Non c&#39;è un passo di ritorno a una v2 (nessun rollback).</p><h3 id="_3-1-canale-di-staging" tabindex="-1">3.1 Canale di staging <a class="header-anchor" href="#_3-1-canale-di-staging" aria-label="Permalink to &quot;3.1 Canale di staging&quot;">​</a></h3><ol><li>Un host <strong>HTTPS</strong> raggiungibile dalle macchine di prova, con un certificato valido per il sistema (l&#39;updater rifiuta <code>http://</code> anche su loopback: <code>AllowInsecureLoopback</code> esiste solo nei test). Va bene un bucket S3/RustFS dietro TLS, una pagina statica o un tunnel; indichiamo l&#39;URL con <code>$STAGING</code> (<code>https://staging.example/desktop</code>).</li><li>Una coppia di chiavi di staging: <code>task release-tool</code> poi <code>bin/release gen-key</code> (stampa privata e pubblica; non salva nulla). Tenere la privata in <code>$STAGING_KEY</code> (variabile d&#39;ambiente o file) e la pubblica in <code>$STAGING_PUB</code>. Mai le chiavi di produzione.</li><li>Il canale è <code>$STAGING/stable/manifest.json</code> più <code>manifest.json.sig</code>; gli artefatti stanno sotto <code>$STAGING/</code>.</li></ol><h3 id="_3-2-le-due-build" tabindex="-1">3.2 Le due build <a class="header-anchor" href="#_3-2-le-due-build" aria-label="Permalink to &quot;3.2 Le due build&quot;">​</a></h3><p>Tutte con <code>UPDATE_PUBLIC_KEY=$STAGING_PUB</code> e <code>UPDATE_BASE_URL=$STAGING</code>, <strong>senza</strong> <code>ALLOW_UNSIGNED_UPDATES</code>:</p><table tabindex="0"><thead><tr><th>Build</th><th>Da dove</th><th>Versione</th><th>Note</th></tr></thead><tbody><tr><td>A, la «1.3.4» di partenza</td><td><code>git worktree add ../mb-134 v1.3.4</code>, poi gli script del tag (CLI Wails v2)</td><td><code>1.3.4</code></td><td>Stessa versione del rilascio vero, ma chiave e URL di staging. Non si installa mai su una macchina con la 1.3.4 vera.</td></tr><tr><td>B, v3</td><td>il ramo della migrazione (questo repository)</td><td><code>1.3.5</code></td><td><code>task release-desktop OS=&lt;os&gt; V=1.3.5</code> e i pacchetti.</td></tr></tbody></table><p>I nomi dei file sono <code>memobrain-&lt;versione&gt;-&lt;os&gt;-&lt;arch&gt;.&lt;ext&gt;</code> (<code>dmg</code>, <code>exe</code> NSIS, <code>AppImage</code>, <code>deb</code>), uguali nelle due epoche.</p><h3 id="_3-3-pubblicare-il-passo" tabindex="-1">3.3 Pubblicare il passo <a class="header-anchor" href="#_3-3-pubblicare-il-passo" aria-label="Permalink to &quot;3.3 Pubblicare il passo&quot;">​</a></h3><p>Con gli artefatti della build B in una cartella <code>art/</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Windows: l&#39;installer esce da \`release-desktop\` con un nome fisso (§0) che \`gen-manifest\` scarta in silenzio</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># (classify, tools/release/main.go:64-67: servono almeno quattro parti); va rinominato come in release.yml</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/desktop/build/bin/memobrain-amd64-installer.exe</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> art/memobrain-1.3.5-windows-amd64.exe</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bin/release</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gen-manifest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -channel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stable</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -version</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.3.5</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sequence</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -artifacts-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> art</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -base-url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $STAGING </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manifest.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bin/release</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sign-manifest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manifest.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -key-env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> STAGING_KEY</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # scrive manifest.json.sig</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bin/release</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify-manifest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manifest.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -pubkey</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $STAGING_PUB</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># caricare art/* sotto $STAGING/ e manifest.json + manifest.json.sig sotto $STAGING/stable/</span></span></code></pre></div><p>Dopo <code>gen-manifest</code> controllare che <code>manifest.json</code> elenchi un artefatto per ogni sistema operativo provato: un file con il nome sbagliato non dà errore e manca dal manifest. Non alzare <code>-min-version</code> in questa prova (la <code>sequence</code> deve crescere a ogni manifest pubblicato: il client rifiuta come replay uno più vecchio).</p><h3 id="_3-4-svolgimento-per-ogni-os" tabindex="-1">3.4 Svolgimento (per ogni OS) <a class="header-anchor" href="#_3-4-svolgimento-per-ogni-os" aria-label="Permalink to &quot;3.4 Svolgimento (per ogni OS)&quot;">​</a></h3><ol><li>Installare la build <strong>A</strong> (macOS: in <code>/Applications</code>; Windows: installer; Linux: AppImage e, in una seconda sessione, <code>.deb</code>). Aprire un vault di prova con note, un disegno e un account di staging se serve; annotare: cartella di installazione, data dir, vault recenti, impostazioni e <strong>registro</strong> su Windows (<code>reg query HKLM\\Software\\Classes\\memobrain</code>, chiave Uninstall), <code>%AppData%\\MemoBrain Notes.exe</code>.</li><li>Pubblicare il passo 1 (versione 1.3.5, build B). Nell&#39;app: <em>Verifica aggiornamenti</em> (comando o impostazioni; canale <em>Stabile</em>). Deve comparire la 1.3.5; scaricare e <em>Installa e riavvia</em> (W: UAC, installer silenzioso a app chiusa e riavvio; M: l&#39;app esce, il <code>.dmg</code> viene montato e la <code>.app</code> sostituita; L AppImage: file sostituito in posizione, riavvio a mano; L deb: <code>xdg-open</code> della cartella e <code>sudo apt install</code>).</li><li>Dopo il riavvio sulla <strong>v3</strong> verificare (P0 se uno fallisce): <ul><li>la versione in About è 1.3.5 e c&#39;è <strong>una sola</strong> installazione (W: una voce in <em>App installate</em>, stessa cartella; M: un solo <code>MemoBrain Notes.app</code>; L: un solo eseguibile);</li><li><strong>data dir, vault recenti, impostazioni e login</strong> sono quelli del punto 1, senza rifare nulla;</li><li>lo schema <code>memobrain://</code> funziona ancora (W: chiave di registro intatta; M: <code>open memobrain://open?...</code>);</li><li>W: <code>%AppData%\\MemoBrain Notes.exe</code> è la stessa cartella (nessuna seconda cartella di dati di WebView2), la stessa finestra WebView2 conserva le impostazioni dell&#39;interfaccia;</li><li>il giro di chiusura con una nota modificata (§2) passa sulla build aggiornata.</li></ul></li><li>Prova negativa: con l&#39;updater in v3 puntato a un manifest con firma alterata (un byte cambiato in <code>manifest.json.sig</code>) l&#39;app mostra l&#39;errore e <strong>non</strong> scarica nulla.</li><li>Smontare il canale: cancellare le chiavi di staging, disinstallare le due build dalle macchine di prova.</li></ol><p>Esito atteso: l&#39;aggiornamento riesce sui tre sistemi operativi senza perdere cartella di installazione, schema URL, data dir né dati di WebView2. Un solo fallimento è un P0.</p><h2 id="_4-registro-dell-esito" tabindex="-1">4. Registro dell&#39;esito <a class="header-anchor" href="#_4-registro-dell-esito" aria-label="Permalink to &quot;4. Registro dell&#39;esito&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Sistema operativo</th><th>Data</th><th>Chi</th><th>Versione provata</th><th>P0</th><th>P1</th><th>P2</th><th>Note</th></tr></thead><tbody><tr><td>macOS (arm64)</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>macOS (Intel)</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Windows 11 (amd64)</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Ubuntu 22.04 (amd64)</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Ubuntu 24.04 (amd64)</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table>`,58)])])}const m=a(n,[["render",t]]);export{g as __pageData,m as default};
